UPDATE truss.row_home_operation o SET effect_generation = o.effect_generation + 1, phase = 'admitted', readiness_generation = NULL, sealed_generation = NULL, application_generation = NULL, application_result_bytes = NULL WHERE o.original_writer_xid = pg_catalog.pg_current_xact_id_if_assigned() AND o.operation_ordinal = $1::bigint AND o.effect_generation = $2::bigint AND o.original_context_bytes = $3::pg_catalog.bytea AND o.phase = 'admitted' AND o.effect_generation >= 0 AND o.effect_generation < 9223372036854775807 AND NOT EXISTS (SELECT 1 FROM truss.row_home_journal_stage s WHERE s.original_writer_xid = o.original_writer_xid AND s.operation_ordinal = o.operation_ordinal AND s.stage_name IN ('final', 'reserved', 'publication')) RETURNING o.original_writer_xid::pg_catalog.text AS original_writer_xid, o.operation_ordinal::pg_catalog.text AS operation_ordinal, o.operation_kind::pg_catalog.text AS operation_kind, o.phase::pg_catalog.text AS phase, o.effect_generation::pg_catalog.text AS effect_generation, o.readiness_generation::pg_catalog.text AS readiness_generation, o.sealed_generation::pg_catalog.text AS sealed_generation, o.application_generation::pg_catalog.text AS application_generation, pg_catalog.encode(o.original_context_bytes, 'hex') AS original_context_bytes_hex, pg_catalog.encode(o.original_definition_bytes, 'hex') AS original_definition_bytes_hex, pg_catalog.encode(o.original_input_bytes, 'hex') AS original_input_bytes_hex, pg_catalog.encode(o.original_prestate_bytes, 'hex') AS original_prestate_bytes_hex, pg_catalog.encode(o.admitted_candidate_bytes, 'hex') AS admitted_candidate_bytes_hex, pg_catalog.encode(o.effect_obligation_bytes, 'hex') AS effect_obligation_bytes_hex, pg_catalog.encode(o.original_group_custody_bytes, 'hex') AS original_group_custody_bytes_hex, pg_catalog.encode(o.application_result_bytes, 'hex') AS application_result_bytes_hex